[9000001] = {9000001, "The\u{0020}atmosphere\u{0020}here\u{0020}is\u{0020}truly\u{0020}comforting.", "0", "0", "0", "这里的气氛真让人舒心。"},
[9000002] = {9000002, "I\u{0020}haven't\u{0020}been\u{0020}home\u{0020}in\u{0020}a\u{0020}very\u{0020}long\u{0020}time.\u{0020}I'll\u{0020}bring\u{0020}some\u{0020}local\u{0020}favorites\u{0020}back\u{0020}with\u{0020}me\u{0020}once\u{0020}I\u{0020}have\u{0020}the\u{0020}chance.\u{0020}Ah,\u{0020}and\u{0020}I\u{0020}should\u{0020}bring\u{0020}back\u{0020}some\u{0020}snacks\u{0020}too,\u{0020}V\u{0020}and\u{0020}the\u{0020}others\u{0020}will\u{0020}be\u{0020}thrilled!", "0", "0", "0", "好久没回家了，等下次有机会带点这里的特产回去吧，对了...还得多带点零食回去，小薇她们一定会高兴的！"},
[9000003] = {9000003, "I\u{0020}love\u{0020}cooking\u{0020}and\u{0020}seeing\u{0020}everyone's\u{0020}happy\u{0020}smiles.\u{0020}If\u{0020}there's\u{0020}a\u{0020}chance,\u{0020}let\u{0020}me\u{0020}treat\u{0020}everyone\u{0020}to\u{0020}a\u{0020}feast.", "0", "0", "0", "我喜欢料理，也喜欢大家幸福的笑容。如果有机会的话，就让我做一顿大餐犒劳大家吧。"},
[9000004] = {9000004, "I\u{0020}used\u{0020}to\u{0020}pat\u{0020}my\u{0020}younger\u{0020}siblings\u{0020}on\u{0020}the\u{0020}head\u{0020}and\u{0020}tuck\u{0020}them\u{0020}in\u{0020}to\u{0020}sleep.\u{0020}Being\u{0020}patted\u{0020}on\u{0020}the\u{0020}head\u{0020}by\u{0020}the\u{0020}navigator...\u{0020}it's\u{0020}a\u{0020}special\u{0020}feeling,\u{0020}hehe.", "0", "0", "0", "以前都是我摸着弟弟妹妹的头，哄她们入睡。像这样被领航摸着头...有一种特别的感觉，嘻嘻。"},
[9000005] = {9000005, "Navigator\u{0020}really\u{0020}likes\u{0020}patting\u{0020}my\u{0020}head,\u{0020}huh,\u{0020}hehe.", "0", "0", "0", "领航真的很喜欢摸头呢，嘻嘻。"},
[9000006] = {9000006, "Navigator,\u{0020}please\u{0020}don't\u{0020}tease\u{0020}me.\u{0020}I\u{0020}know\u{0020}I've\u{0020}gained\u{0020}some\u{0020}weight\u{0020}recently,\u{0020}and\u{0020}I'll\u{0020}seriously\u{0020}start\u{0020}my\u{0020}diet\u{0020}plan.", "0", "0", "0", "领航，不要捉弄我了。我知道最近胖了，我会认真执行减肥计划的。"},
[9000007] = {9000007, "Navigator,\u{0020}haha...\u{0020}stop...\u{0020}it's\u{0020}so\u{0020}itchy,\u{0020}haha...\u{0020}I'm\u{0020}going\u{0020}to\u{0020}get\u{0020}mad!", "0", "0", "0", "领航，哈哈哈...别...别摸了，好痒啦，哈哈哈哈哈哈...我要生气了哦！"},
[9000008] = {9000008, "Hey—Navigator!\u{0020}If\u{0020}you\u{0020}think\u{0020}I\u{0020}won't\u{0020}get\u{0020}mad\u{0020}no\u{0020}matter\u{0020}what,\u{0020}you're\u{0020}so\u{0020}wrong!\u{0020}Don't\u{0020}underestimate\u{0020}me;\u{0020}when\u{0020}I\u{0020}get\u{0020}mad,\u{0020}it's\u{0020}really,\u{0020}really\u{0020}scary!", "0", "0", "0", "诶——领航！要是您觉得不管如何我都不会生气的话，那您就大错特错了！别看我这样，生气起来可是很、很可怕的哦！"},
[9000009] = {9000009, "Navigator,\u{0020}enough\u{0020}is\u{0020}enough!", "0", "0", "0", "领航！要适可而止！"},
[9000010] = {9000010, "Navigator,\u{0020}welcome\u{0020}back!\u{0020}Would\u{0020}you\u{0020}like\u{0020}something\u{0020}to\u{0020}drink?", "0", "0", "0", "领航，欢迎回来，需要喝点什么吗？"},
[9000011] = {9000011, "Phew...\u{0020}I'll\u{0020}try\u{0020}my\u{0020}best,\u{0020}Navigator!", "0", "0", "0", "呼....我会努力的，领航！"},
[9000012] = {9000012, "I...\u{0020}I\u{0020}want\u{0020}to\u{0020}do\u{0020}whatever\u{0020}I\u{0020}can\u{0020}to\u{0020}help\u{0020}alleviate\u{0020}the\u{0020}navigator's\u{0020}worries,\u{0020}is\u{0020}that\u{0020}okay?", "0", "0", "0", "我...我想尽自己所能地帮领航分忧解难，可以吗？"},
[9000013] = {9000013, "Franca,\u{0020}dressed\u{0020}in\u{0020}her\u{0020}Aegis\u{0020}uniform,\u{0020}is\u{0020}talking\u{0020}to\u{0020}her\u{0020}family\u{0020}as\u{0020}usual.\u{0020}How's\u{0020}the\u{0020}weather\u{0020}back\u{0020}home\u{0020}recently?\u{0020}How's\u{0020}the\u{0020}restaurant\u{0020}doing\u{0020}after\u{0020}I\u{0020}left?\u{0020}Without\u{0020}my\u{0020}help,\u{0020}will\u{0020}it\u{0020}be\u{0020}too\u{0020}busy\u{0020}at\u{0020}home?\u{0020}Oh,\u{0020}and\u{0020}if\u{0020}Vivian\u{0020}wants\u{0020}to\u{0020}study\u{0020}in\u{0020}the\u{0020}capital,\u{0020}she'll\u{0020}have\u{0020}to\u{0020}work\u{0020}hard;\u{0020}she\u{0020}can\u{0020}take\u{0020}the\u{0020}exams\u{0020}next\u{0020}year\u{0020}and\u{0020}come\u{0020}here.\u{0020}I've\u{0020}saved\u{0020}up\u{0020}quite\u{0020}a\u{0020}bit\u{0020}of\u{0020}money\u{0020}and\u{0020}can\u{0020}almost\u{0020}buy\u{0020}a\u{0020}house\u{0020}in\u{0020}the\u{0020}capital,\u{0020}so\u{0020}Mom\u{0020}and\u{0020}Dad\u{0020}can\u{0020}come\u{0020}and\u{0020}live\u{0020}here\u{0020}too...\u{0020}Franca\u{0020}carefully\u{0020}notes\u{0020}all\u{0020}these\u{0020}things\u{0020}in\u{0020}her\u{0020}heart.\u{0020}It's\u{0020}wonderful.", "0", "0", "0", "弗兰卡在艾吉斯内部穿着的服饰之一，弗兰卡，像往常一样在与自己家人通话。最近家那边的天气怎么样？在我走之后餐馆的生意怎么样了，没有我帮忙的话，家里会不会很忙？对了小薇想要来首都念书的话可要好好努力了，明年就可以考到这里了，我攒了不少的钱快可以在首都买房子，爸爸妈妈也可以一起来住……一点一滴，弗兰卡仔细地把这些事情记在心里。真好呀。"},
[9000014] = {9000014, "Unlock\u{0020}Commander's\u{0020}Office", "0", "0", "0", "测试文本"},
[9001001] = {9001001, "This\u{0020}place...\u{0020}is\u{0020}fine.\u{0020}But\u{0020}if\u{0020}it\u{0020}were\u{0020}up\u{0020}to\u{0020}me\u{0020}to\u{0020}decorate,\u{0020}I'm\u{0020}sure\u{0020}I\u{0020}could\u{0020}make\u{0020}it\u{0020}look\u{0020}much\u{0020}better!", "0", "0", "0", "这个地方...马马虎虎吧。不过要是让本小姐来装修的话，肯定能布置得更好！"},
[9001002] = {9001002, "Hmm...\u{0020}I've\u{0020}decided!\u{0020}Navigator,\u{0020}even\u{0020}if\u{0020}our\u{0020}mission\u{0020}can't\u{0020}be\u{0020}made\u{0020}public,\u{0020}I'm\u{0020}going\u{0020}to\u{0020}prove\u{0020}to\u{0020}everyone\u{0020}that\u{0020}the\u{0020}Special\u{0020}Joint\u{0020}Force\u{0020}is\u{0020}the\u{0020}best\u{0020}driver\u{0020}unit\u{0020}in\u{0020}Aegis!", "0", "0", "0", "嗯...我决定好了！领航，就算我们的任务不能公之于众，我也要向所有人证明特别联合部队是艾吉斯最优秀的驾驶员部队！"},
[9001003] = {9001003, "I\u{0020}wonder\u{0020}how\u{0020}that\u{0020}old\u{0020}man\u{0020}is\u{0020}doing\u{0020}now...\u{0020}Wait,\u{0020}I'm\u{0020}not\u{0020}worried\u{0020}about\u{0020}him,\u{0020}I\u{0020}just\u{0020}don't\u{0020}want\u{0020}him\u{0020}to\u{0020}tarnish\u{0020}my\u{0020}reputation.", "0", "0", "0", "也不知道臭老爹现在怎么样了...我可不是在担心他，只是怕因为他的事情而败坏了本小姐的名声而已。"},
[9001004] = {9001004, "2,\u{0020}3...\u{0020}Nothing,\u{0020}I'm\u{0020}just\u{0020}counting\u{0020}how\u{0020}many\u{0020}times\u{0020}you've\u{0020}patted\u{0020}me.\u{0020}I'll\u{0020}return\u{0020}the\u{0020}patting\u{0020}later.", "0", "0", "0", "2、3......没什么，我只是在数你摸了多少次而已，待会就会全部奉还的。"},
[9001005] = {9001005, "Mood...\u{0020}it's\u{0020}not\u{0020}as\u{0020}bad\u{0020}as\u{0020}I\u{0020}thought.", "0", "0", "0", "心情...微妙得没那么糟糕。"},
[9001006] = {9001006, "You...\u{0020}pervert!\u{0020}Can't\u{0020}you\u{0020}be\u{0020}more\u{0020}gentle?!", "0", "0", "0", "你这...变态！你就不能更加绅士一点，更加温柔一点吗！？"},
[9001007] = {9001007, "I'll\u{0020}kill\u{0020}you,\u{0020}I\u{0020}swear\u{0020}I'll\u{0020}kill\u{0020}you!\u{0020}I've\u{0020}never\u{0020}been\u{0020}humiliated\u{0020}like\u{0020}this\u{0020}before,\u{0020}you\u{0020}better\u{0020}be\u{0020}ready!\u{0020}\"I'll\u{0020}take\u{0020}care\u{0020}of\u{0020}you\"?...\u{0020}What\u{0020}are\u{0020}you\u{0020}talking\u{0020}about,\u{0020}no...\u{0020}You\u{0020}cannot\u{0020}get\u{0020}away\u{0020}with\u{0020}this!", "0", "0", "0", "杀了你，绝对要杀了你！本小姐从来没有受到过这种屈辱，你给我做好心理准备吧！“我会负责的”？...你在说什么傻话，不...不要以为这样就可以应付我！"},
[9001008] = {9001008, "Wah—It's\u{0020}so\u{0020}cold...\u{0020}What\u{0020}are\u{0020}you\u{0020}doing?\u{0020}Don't\u{0020}scare\u{0020}me\u{0020}like\u{0020}that!", "0", "0", "0", "呜——好冷...突然间在做什么？不要吓我啦！"},
[9001009] = {9001009, "Hey!\u{0020}You\u{0020}haven't\u{0020}done\u{0020}this\u{0020}to\u{0020}other\u{0020}girls,\u{0020}have\u{0020}you...\u{0020}It\u{0020}looks\u{0020}like\u{0020}I\u{0020}need\u{0020}to\u{0020}set\u{0020}things\u{0020}straight!", "0", "0", "0", "喂！你不会对其他的女孩子也这么做了吧...看来必须要拨乱反正了！"},
[9001010] = {9001010, "Navigator,\u{0020}welcome\u{0020}back...\u{0020}What's\u{0020}with\u{0020}that\u{0020}expression,\u{0020}you\u{0020}think\u{0020}I'd\u{0020}throw\u{0020}a\u{0020}tantrum\u{0020}here\u{0020}just\u{0020}because\u{0020}I'm\u{0020}bored?\u{0020}Sorry\u{0020}to\u{0020}disappoint\u{0020}you,\u{0020}but\u{0020}I'm\u{0020}not\u{0020}that\u{0020}kind\u{0020}of\u{0020}person.", "0", "0", "0", "领航，欢迎回……你这是什么表情，你觉得我会因为无聊在这里大闹特闹吗？让你失望了，本小姐不是那种无理取闹的人。"},
[9001011] = {9001011, "Hmph~\u{0020}I'll\u{0020}finish\u{0020}any\u{0020}job\u{0020}nicely,\u{0020}no\u{0020}matter\u{0020}what\u{0020}it\u{0020}is.", "0", "0", "0", "哼哼~不管什么样的工作，我都会漂亮地完成的。"},
[9001012] = {9001012, "Hey,\u{0020}Navigator,\u{0020}what\u{0020}do\u{0020}you\u{0020}usually\u{0020}do...\u{0020}Nothing,\u{0020}I\u{0020}just\u{0020}wanted\u{0020}to\u{0020}know\u{0020}a\u{0020}little\u{0020}more\u{0020}about\u{0020}you,\u{0020}is\u{0020}that\u{0020}okay?", "0", "0", "0", "喂，领航，你平常都在做什么...没什么，只是想稍微了解一下你而已，不行么?"},
[9001013] = {9001013, "Charlissa's\u{0020}outfit.\u{0020}Finally,\u{0020}I\u{0020}don't\u{0020}have\u{0020}to\u{0020}be\u{0020}like\u{0020}a\u{0020}dress-up\u{0020}doll,\u{0020}being\u{0020}dressed\u{0020}in\u{0020}different\u{0020}clothes\u{0020}every\u{0020}day.\u{0020}Charlissa\u{0020}is\u{0020}probably\u{0020}10000%\u{0020}satisfied\u{0020}with\u{0020}this\u{0020}outfit;\u{0020}as\u{0020}long\u{0020}as\u{0020}you\u{0020}can\u{0020}meet\u{0020}her\u{0020}when\u{0020}she's\u{0020}not\u{0020}in\u{0020}her\u{0020}giantess\u{0020}form,\u{0020}she'll\u{0020}be\u{0020}wearing\u{0020}this\u{0020}outfit.\u{0020}It's\u{0020}said\u{0020}she\u{0020}ordered\u{0020}20\u{0020}sets\u{0020}of\u{0020}the\u{0020}same\u{0020}outfit.", "0", "0", "0", "查丽莎的服饰，终于不用像是换装娃娃那样，被每天照顾着穿上各式各样的衣服了，查丽莎对这身衣服的满意程度大概有10000分，只要是你能遇见不是巨大化的查丽莎，她一定穿着这身衣服，据说她定制了20套同样的衣服。"},
[9001014] = {9001014, "Novice\u{0020}Event\u{0020}Rewards", "0", "0", "0", "测试文本"},
[9002001] = {9002001, "Is\u{0020}this\u{0020}where\u{0020}Navigator\u{0020}usually\u{0020}stays?\u{0020}*sniff*\u{0020}The\u{0020}smell\u{0020}is\u{0020}comforting...\u{0020}Ah!\u{0020}P-please,\u{0020}forget\u{0020}what\u{0020}I\u{0020}just\u{0020}said...", "0", "0", "0", "这就是领航平时待的地方吗？（嗅嗅）有种让人安心的味道......啊！请，请忘掉刚才的话......"},
[9002002] = {9002002, "...Captain\u{0020}Angelica.\u{0020}I've\u{0020}been\u{0020}working\u{0020}hard,\u{0020}you\u{0020}know...\u{0020}Have\u{0020}you\u{0020}noticed?", "0", "0", "0", "......安洁莉卡队长。我有好好地在努力哦......你有看到吗。"},
[9002003] = {9002003, "What?\u{0020}Are\u{0020}you\u{0020}worried\u{0020}about\u{0020}me?\u{0020}Don't\u{0020}worry,\u{0020}Navigator,\u{0020}I\u{0020}have\u{0020}my\u{0020}teammates...\u{0020}Whether\u{0020}now\u{0020}or\u{0020}in\u{0020}the\u{0020}past,\u{0020}that\u{0020}hasn't\u{0020}changed.", "0", "0", "0", "什么？担心我吗......放心，领航，我还有重要的队友们呢......不管是现在的，亦或者过去，一直没有变。"},
[9002004] = {9002004, "I\u{0020}haven't\u{0020}felt\u{0020}this\u{0020}relaxed\u{0020}in\u{0020}a\u{0020}long\u{0020}time...\u{0020}Navigator,\u{0020}please\u{0020}stay\u{0020}by\u{0020}my\u{0020}side\u{0020}a\u{0020}little\u{0020}longer.", "0", "0", "0", "我已经好久没有......这么放松过了......领航，请在我身边再呆一会吧。"},
[9002005] = {9002005, "Hmm...\u{0020}I\u{0020}was\u{0020}wondering\u{0020}what\u{0020}it\u{0020}would\u{0020}be\u{0020}like\u{0020}if\u{0020}days\u{0020}like\u{0020}these\u{0020}could\u{0020}last\u{0020}ten\u{0020}or\u{0020}twenty\u{0020}years.", "0", "0", "0", "嗯......我在想，如果这样的日子能持续下去，十年，二十年......会是什么样呢?"},
[9002006] = {9002006, "Whoa—Na-navigator,\u{0020}please\u{0020}don't\u{0020}do\u{0020}that!\u{0020}Someone\u{0020}could\u{0020}come\u{0020}in\u{0020}here\u{0020}at\u{0020}any\u{0020}moment.", "0", "0", "0", "呜哇啊——领、领航，请不要这样！这里、随时会有人进来的。"},
[9002007] = {9002007, "Ah—Is\u{0020}this\u{0020}also\u{0020}part\u{0020}of\u{0020}the\u{0020}secretary's\u{0020}duties?\u{0020}You\u{0020}don't\u{0020}mean\u{0020}it?\u{0020}Ah—", "0", "0", "0", "呜——这、这也是秘书官要负责的事情吗？不、不小心的？呜——"},
[9002008] = {9002008, "If\u{0020}Navigator\u{0020}wants\u{0020}to\u{0020}sleep,\u{0020}you\u{0020}can\u{0020}rest\u{0020}on\u{0020}the\u{0020}sofa\u{0020}for\u{0020}a\u{0020}bit.\u{0020}Why...\u{0020}are\u{0020}you\u{0020}staring\u{0020}at\u{0020}my\u{0020}legs?", "0", "0", "0", "领航想要睡觉可以去沙发上靠一会哦。为什么......盯着我的腿看。"},
[9002009] = {9002009, "Huh,\u{0020}suddenly\u{0020}coming\u{0020}so\u{0020}close...\u{0020}Navigator,\u{0020}what's\u{0020}up\u{0020}with\u{0020}you?", "0", "0", "0", "唔，突然凑那么近............领航，你怎么了？"},
[9002010] = {9002010, "Navigator—(surprised)\u{0020}You're\u{0020}here\u{0020}a\u{0020}bit\u{0020}earlier\u{0020}than\u{0020}usual\u{0020}today.\u{0020}You...\u{0020}\u{0020}you\u{0020}didn't\u{0020}see\u{0020}anything\u{0020}just\u{0020}now,\u{0020}right?", "0", "0", "0", "领航——（吃惊）今天稍微来得比平时早一点呢。......你......刚刚什么都没看到吧？"},
[9002011] = {9002011, "To\u{0020}be\u{0020}the\u{0020}navigator's\u{0020}secretary...?\u{0020}Can\u{0020}I\u{0020}really\u{0020}do\u{0020}it?\u{0020}...No,\u{0020}I\u{0020}can\u{0020}do\u{0020}it,\u{0020}Dolores\u{0020}as\u{0020}the\u{0020}navigator's\u{0020}secretary,\u{0020}will\u{0020}do\u{0020}my\u{0020}best!", "0", "0", "0", "由我来当领航的秘书官......？我真的可以吗？......不、我一定可以的，多洛莉丝作为领航的秘书官、会加油的！"},
[9002012] = {9002012, "I\u{0020}kept\u{0020}my\u{0020}promise\u{0020}with\u{0020}you,\u{0020}Navigator.\u{0020}Allow\u{0020}me\u{0020}to\u{0020}report\u{0020}once\u{0020}more,\u{0020}Dolores\u{0020}has\u{0020}returned\u{0020}safely.", "0", "0", "0", "我遵守了与您的约定，领航。容我再通报一次，多洛莉丝平安归来了。"},
[9002013] = {9002013, "Dolores's\u{0020}casual\u{0020}attire\u{0020}in\u{0020}the\u{0020}Third\u{0020}Laboratory,\u{0020}this\u{0020}was\u{0020}Dolores's\u{0020}first\u{0020}work\u{0020}uniform.\u{0020}Even\u{0020}as\u{0020}time\u{0020}passes,\u{0020}her\u{0020}longing\u{0020}for\u{0020}Angelica\u{0020}persists.\u{0020}This\u{0020}longing\u{0020}should\u{0020}not,\u{0020}and\u{0020}never\u{0020}has,\u{0020}restricted\u{0020}Dolores'\u{0020}motions.\u{0020}Instead,\u{0020}it\u{0020}has\u{0020}become\u{0020}a\u{0020}bittersweet\u{0020}desire\u{0020}that\u{0020}pushes\u{0020}Dolores\u{0020}forward.", "0", "0", "0", "多洛莉丝在第三研究室的常服，【嫉妒】事件结束后，艾吉斯对于多洛莉丝的去留给出了三个建议。第一个建议，假如多洛莉丝不愿意再有作为驾驶员的意志，可以退役转入艾吉斯的内务部门。第二个建议，不少小队被多洛莉丝的意志所打动，她们愿意为多洛莉丝留出一个位置。第三个建议，作为第三研究室防卫班的队长，重整防卫班，但是这会非常辛苦，而且因为【嫉妒】的前车之鉴，防卫班的新人在适格率和战斗适应性方面一定会比多洛莉丝高。………………我决定了。"},
[9002014] = {9002014, "Coming\u{0020}Soon", "0", "0", "0", "测试文本"},
[9003001] = {9003001, "From\u{0020}here,\u{0020}you\u{0020}can\u{0020}see\u{0020}the\u{0020}distant\u{0020}town,\u{0020}it's\u{0020}really\u{0020}nice.", "0", "0", "0", "从这里可以眺望到远处的城镇，真好啊。"},
[9003002] = {9003002, "Navigator...\u{0020}suddenly\u{0020}asking\u{0020}this\u{0020}might\u{0020}seem\u{0020}strange\u{0020}to\u{0020}you,\u{0020}but\u{0020}can\u{0020}you\u{0020}tell\u{0020}me,\u{0020}what\u{0020}are\u{0020}you\u{0020}fighting\u{0020}for?\u{0020}...I\u{0020}see,\u{0020}thank\u{0020}you.", "0", "0", "0", "领航...突然这么问或许您会觉得奇怪，但您能告诉我，您是为了什么而战吗？......这样啊，嗯，谢谢。"},
[9003003] = {9003003, "Whew...\u{0020}time\u{0020}has\u{0020}passed\u{0020}so\u{0020}fast...\u{0020}I'm\u{0020}a\u{0020}bit\u{0020}hungry,\u{0020}shall\u{0020}we\u{0020}have\u{0020}a\u{0020}meal\u{0020}together,\u{0020}Navigator?", "0", "0", "0", "呼...不知不觉已经过去这么久了......稍微有些饿了呢，待会要一起用餐吗，领航？"},
[9003004] = {9003004, "Hey,\u{0020}is\u{0020}there\u{0020}something\u{0020}on\u{0020}my\u{0020}face?", "0", "0", "0", "诶,我脸上有什么奇怪的东西吗？"},
[9003005] = {9003005, "Is\u{0020}it\u{0020}tiring\u{0020}for\u{0020}you\u{0020}to\u{0020}pat\u{0020}my\u{0020}head\u{0020}like\u{0020}this?\u{0020}Should\u{0020}I\u{0020}crouch\u{0020}down\u{0020}for\u{0020}you,\u{0020}Navigator?", "0", "0", "0", "这样子摸头很累吧，需要我蹲下来吗？领航？"},
[9003006] = {9003006, "If\u{0020}you\u{0020}keep\u{0020}doing\u{0020}this,\u{0020}it'll\u{0020}make\u{0020}me\u{0020}uncomfortable,\u{0020}Navigator.", "0", "0", "0", "如果再继续的话，会让我困扰的，领航。"},
[9003007] = {9003007, "Staying\u{0020}fit\u{0020}is\u{0020}a\u{0020}must\u{0020}for\u{0020}warriors.\u{0020}The\u{0020}difficulty\u{0020}is\u{0020}no\u{0020}less\u{0020}than\u{0020}fighting\u{0020}the\u{0020}sins.\u{0020}The\u{0020}biggest\u{0020}challenge\u{0020}is\u{0020}knowing\u{0020}how\u{0020}to\u{0020}resist\u{0020}your\u{0020}favorite\u{0020}food\u{0020}when\u{0020}it\u{0020}appears.", "0", "0", "0", "保持良好的身材是战士的必修课。其难度不比与原罪厮杀低，主要的考验在于当喜欢的食物出现在面前时，该如何保持克制。"},
[9003008] = {9003008, "Did\u{0020}your\u{0020}hand\u{0020}slip?\u{0020}If\u{0020}it's\u{0020}Navigator,\u{0020}then...\u{0020}let's\u{0020}just\u{0020}call\u{0020}it\u{0020}an\u{0020}accident.", "0", "0", "0", "手滑了吗？如果是领航的话，姑且...就当作是个意外了。"},
[9003009] = {9003009, "Is\u{0020}this\u{0020}a\u{0020}new\u{0020}training\u{0020}subject?\u{0020}Indeed,\u{0020}I've\u{0020}skipped\u{0020}a\u{0020}few\u{0020}leg\u{0020}days.\u{0020}Come\u{0020}on,\u{0020}Navigator,\u{0020}no\u{0020}matter\u{0020}how\u{0020}uncomfortable\u{0020}it\u{0020}is,\u{0020}I\u{0020}will\u{0020}make\u{0020}it\u{0020}through.", "0", "0", "0", "这是新的训练科目吗？的确，平时疏忽了对于双腿的锻炼，来吧，领航，无论多痛苦我都会忍受住的。"},
[9003010] = {9003010, "I\u{0020}will\u{0020}take\u{0020}any\u{0020}work\u{0020}seriously.", "0", "0", "0", "无论是什么样的工作，我都会认真面对。"},
[9003011] = {9003011, "Is\u{0020}there\u{0020}a\u{0020}new\u{0020}mission?\u{0020}Understood.", "0", "0", "0", "是有新任务派发吗？明白。"},
[9003012] = {9003012, "As\u{0020}the\u{0020}leader\u{0020}of\u{0020}the\u{0020}joint\u{0020}force,\u{0020}I\u{0020}want\u{0020}to\u{0020}be\u{0020}of\u{0020}help\u{0020}to\u{0020}Navigator\u{0020}in\u{0020}every\u{0020}way,\u{0020}I\u{0020}believe\u{0020}this\u{0020}is\u{0020}my\u{0020}duty.", "0", "0", "0", "作为联合部队的领队，我想在各方面都能帮到领航，我认为这是我应尽的责任。"},
[9003013] = {9003013, "Julius's\u{0020}work\u{0020}attire.\u{0020}Adjusting\u{0020}the\u{0020}tie,\u{0020}placing\u{0020}the\u{0020}hair\u{0020}accessories.\u{0020}Julius\u{0020}appears\u{0020}softer\u{0020}in\u{0020}her\u{0020}work\u{0020}attire.\u{0020}In\u{0020}the\u{0020}drowsy\u{0020}afternoon,\u{0020}amidst\u{0020}the\u{0020}dense\u{0020}pulp\u{0020}interweaving,\u{0020}the\u{0020}precious\u{0020}honeydew\u{0020}brought\u{0020}thoughts\u{0020}that\u{0020}broke\u{0020}through\u{0020}the\u{0020}mist,\u{0020}filling\u{0020}the\u{0020}spirit\u{0020}with\u{0020}abundance.\u{0020}In\u{0020}the\u{0020}warm\u{0020}sunlight,\u{0020}one\u{0020}can\u{0020}smell\u{0020}the\u{0020}clean\u{0020}and\u{0020}fragrant\u{0020}scent,\u{0020}dust\u{0020}dancing\u{0020}in\u{0020}the\u{0020}gaps\u{0020}of\u{0020}light.\u{0020}Julius,\u{0020}today,\u{0020}tomorrow,\u{0020}will\u{0020}always\u{0020}be\u{0020}here,\u{0020}waiting\u{0020}to\u{0020}serve\u{0020}her\u{0020}Navigator\u{0020}a\u{0020}cup\u{0020}of\u{0020}honey\u{0020}tea.", "0", "0", "0", "朱利乌斯的工作服，束正领带，绑好发饰，换上了工作服的朱利乌斯，仿佛变得不再那么坚毅。昏沉的下午，在稠密的纸浆交迭中，来之不易的蜜露托带着思绪破却了雾霭，精神因此充盈而饱满和煦的阳光中，能闻到干爽芬芳的香味，尘埃透过在光的缝隙中翻滚，朱利乌斯，今天，明天，后天，一直呆在这里，等待着为她的领航递上一杯蜂蜜茶。"},
